export const transitionInterrogationContract = Object.freeze({
  path: Object.freeze(["transition", "inspect"] as const),
  outputSchema: "urn:usf:cli-transition-interrogation:1",
  inputs: Object.freeze([
    Object.freeze({ flag: "--root", valueName: "IRI", required: true, maximumLength: 512,
      pattern: "^(?:urn:[^\\s<>]+|[A-Z][A-Z0-9]*-[1-9][0-9]*)$", defaultValue: null,
      description: "Select one stable semantic work or binding identity. Unresolved issue identities and ambiguous contexts refuse; no profile or current digest is guessed." }),
    Object.freeze({ flag: "--manifest", valueName: "PATH", required: false, maximumLength: 512,
      pattern: "^graph/[^\\s\\\\]+\\.json$", defaultValue: "graph/manifest.json",
      description: "Optionally delimit graph discovery. The selected graph must uniquely derive the root context; absence is not permission to search unrelated profiles." }),
  ]),
});
export const transitionSchemaContract = Object.freeze({
  ...transitionInterrogationContract,
  path: Object.freeze(["transition", "schema"] as const),
  outputSchema: "urn:usf:cli-schema-derivation:1",
});
export const transitionReadContracts = Object.freeze([transitionInterrogationContract, transitionSchemaContract]);
const transitionOptions = transitionInterrogationContract.inputs.map((input) => ({
  syntax: `${input.flag} ${input.valueName}`, description: input.description,
}));
const transitionSynopsisFor = (path: readonly string[]) => `usf ${path.join(" ")} ${transitionInterrogationContract.inputs.map((input) => {
  const value = `${input.flag} ${input.valueName}`;
  return input.required ? value : `[${value}]`;
}).join(" ")}`;
const transitionSynopsis = transitionSynopsisFor(transitionInterrogationContract.path);


// Leaf rows. A group row can only publish one output schema, contact posture
// and authority effect, but its leaves genuinely differ: graph integrity and
// graph lanes contact nothing while graph execute dispatches models, and
// providers policy writes a graph line through the ordinary transaction while
// the rest of the providers group is projection. Publishing the group answer
// for a leaf is therefore not a coarse answer but a wrong one, and an operator
// who has to read handler source to correct it is doing the derivation the
// registry exists to remove.
const envFileOption = { syntax: "--env-file PATH", description: "One owner-only mode-0600 credential file for API-adapter transports; local agent transports authenticate by their own session." } as const;
const stewardGenerationOptions = [
  { syntax: "USF_STEWARD_SESSION_ID", description: "Required opaque session identity in the environment; only its digest is retained, and the digest binds to the immediate parent process." },
  { syntax: "--claim DIGEST --generation DIGEST", description: "Exact current claim and generation; an old generation cannot control its successor." },
] as const;
const stewardWrite = "Writes owner-private local claim state under existing kernel exclusion. No semantic work, construction permission, provider admission, completion or publication authority is created.";
const hermesApplyEffect = "Without --apply this derives a read-only plan from existing evidence and writes nothing. With --apply it contacts eligible external models under explicit operator economic authorization, requires the current USF_STEWARD_CLAIM_ID and USF_STEWARD_GENERATION, and lands admitted results through one bounded atomic semantic transaction; it creates no construction, completion, publication or Git authority.";

